using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class SimplifyRestAreas{public static object Main(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.isDirty||EditorApplication.isPlaying)throw new Exception("Clean edit scene required");File.Copy(scene.path,"output/scene-review/Main.before-restareas-disk.unity",true);EditorSceneManager.SaveScene(scene,"output/scene-review/Main.before-restareas-live.unity",true);var h=GameObject.Find("Hometown").transform;var all=h.GetComponentsInChildren<SpriteRenderer>(true);int removed=0;
foreach(var r in all){if(r.sprite==null)continue;string s=r.sprite.name;bool valley=r.transform.parent.name=="Southern Meadows"&&(s=="Tent_Small_0"||s=="Camp_Decor_1"||s=="Picnic_Basket_0");bool north=r.transform.parent.name=="Northern Woodland"&&(s.StartsWith("Picnic_")||(s=="Benches_1"&&r.transform.position.y>26));if(valley||north){Undo.DestroyObjectImmediate(r.gameObject);removed++;}}
var root=new GameObject("Former rest area natural clearings");root.transform.SetParent(h,false);Undo.RegisterCreatedObjectUndo(root,"Natural clearings");
void Shrub(float x,float y){var src=all.First(r=>r!=null&&r.sprite!=null&&r.sprite.name=="Outdoor_Decor_84");var go=new GameObject("Clearing shrub");go.transform.SetParent(root.transform);go.transform.position=new Vector3(x,y);var r=go.AddComponent<SpriteRenderer>();r.sprite=src.sprite;r.sharedMaterial=src.sharedMaterial;r.sortingOrder=Mathf.RoundToInt(-r.bounds.min.y*16);}
void Rock(float x,float y,int variant){var p=AssetDatabase.LoadAssetAtPath<GameObject>($"Assets/Prefabs/Environment/AnimatedDecor/Bank/Rocks/Rock_{variant}_Anim.prefab");var go=(GameObject)PrefabUtility.InstantiatePrefab(p);go.name="Clearing weathered rock";go.transform.SetParent(root.transform);go.transform.position=new Vector3(x,y);var r=go.GetComponent<SpriteRenderer>();r.sortingOrder=Mathf.RoundToInt(-r.bounds.min.y*16);}
Rock(-115,-28,12);Rock(-113.4f,-28.7f,3);Shrub(-116.3f,-29.4f);Shrub(-114,-30);Rock(-114,-34,5);Shrub(-111.9f,-34.2f);
Rock(-103,30.7f,11);Rock(-101.6f,30,2);Shrub(-104,29);Shrub(-102.4f,28);
EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene,"output/scene-review/Main.after-restareas-live.unity",true);return new{removed};}}
